const STATIC_ASSETS={"/":{"type":"text/html","body":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <meta name=\"color-scheme\" content=\"dark\">\n    <title>Originates | Scalable AI Workflow & Cloud Orchestration</title>\n  <style>\n    *{box-sizing:border-box;margin:0;padding:0;}\n    body{background:#0a0c10;color:#e6edf3;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;line-height:1.6;}\n    a{color:#58a6ff;text-decoration:none;}\n    .container{max-width:1200px;margin:0 auto;padding:0 24px;}\n    header{background:rgba(10,12,16,0.8);backdrop-filter:blur(12px);position:sticky;top:0;z-index:100;border-bottom:1px solid #21262d;}\n    nav{display:flex;justify-content:space-between;align-items:center;height:70px;}\n    .logo{font-size:22px;font-weight:700;letter-spacing:-0.5px;color:#fff;}\n    .logo span{color:#2f81f7;}\n    .nav-links{display:flex;gap:24px;list-style:none;}\n    .nav-links a{color:#8b949e;font-size:14px;font-weight:500;transition:color 0.2s;}\n    .nav-links a:hover{color:#fff;}\n    .btn{display:inline-block;padding:10px 20px;border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;}\n    .btn-primary{background:#238636;color:#fff;}\n    .btn-primary:hover{background:#2ea043;}\n    .hero{padding:100px 0 60px;text-align:center;}\n    .hero h1{font-size:52px;font-weight:800;line-height:1.15;margin-bottom:20px;background:linear-gradient(180deg,#fff,#8b949e);-webkit-background-clip:text;-webkit-text-fill-color:transparent;}\n    .hero p{font-size:20px;color:#8b949e;max-width:760px;margin:0 auto 36px;}\n    .terminal{background:#161b22;border:1px solid #30363d;border-radius:8px;max-width:720px;margin:40px auto 0;text-align:left;box-shadow:0 20px 40px rgba(0,0,0,0.5);}\n    .terminal-header{background:#0d1117;padding:10px 16px;border-bottom:1px solid #30363d;display:flex;gap:8px;}\n    .dot{width:12px;height:12px;border-radius:50%;}\n    .dot-red{background:#ff5f56;}.dot-yellow{background:#ffbd2e;}.dot-green{background:#27c93f;}\n    .terminal-body{padding:20px;font-family:monospace;font-size:14px;color:#7ee787;}\n    .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin:80px 0;text-align:center;}\n    .metric-card{background:#161b22;border:1px solid #21262d;padding:32px;border-radius:8px;}\n    .metric-val{font-size:42px;font-weight:800;color:#2f81f7;}\n    .metric-lbl{color:#8b949e;font-size:14px;margin-top:8px;}\n    .section-title{text-align:center;font-size:32px;margin:80px 0 40px;color:#fff;}\n    .grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;}\n    .card{background:#161b22;border:1px solid #21262d;padding:32px;border-radius:8px;}\n    .card h3{font-size:20px;margin-bottom:12px;color:#fff;}\n    .card p{color:#8b949e;font-size:14px;}\n    .pricing-card{text-align:center;}\n    .price{font-size:36px;font-weight:800;color:#fff;margin:16px 0;}\n    .about{background:#161b22;border:1px solid #21262d;border-radius:8px;padding:40px;margin:80px 0;text-align:center;}\n    footer{border-top:1px solid #21262d;padding:40px 0;text-align:center;color:#8b949e;font-size:14px;}\n    footer a{color:#58a6ff;margin:0 10px;}\n    button,a{touch-action:manipulation} a:focus-visible{outline:3px solid #58a6ff;outline-offset:4px}\n    .availability{margin:24px 0;padding:16px;border:1px solid #30363d;border-radius:8px;color:#b9c3cd;font-size:16px}\n    @media(max-width:700px){.nav-links{display:flex;order:3;width:100%;gap:16px;justify-content:center;flex-wrap:wrap}nav{height:auto;min-height:70px;flex-wrap:wrap;padding:12px 0}.hero{padding-top:56px}.hero h1{font-size:34px}.hero p{font-size:18px}.grid-3,.metrics{grid-template-columns:1fr}.metric-val{font-size:32px}.card,.about{padding:24px}nav{gap:12px}.btn{min-height:44px}.container{padding:0 20px}.terminal-body{overflow-wrap:anywhere}.section-title{font-size:28px}}\n    </style>\n  </head>\n  <body>\n    <header><div class=\"container\"><nav><div class=\"logo\">Originates<span>.dev</span></div><ul class=\"nav-links\"><li><a href=\"#features\">Features</a></li><li><a href=\"#architecture\">Architecture</a></li><li><a href=\"#pricing\">Pricing</a></li><li><a href=\"#about\">About</a></li></ul><a class=\"btn btn-primary\" href=\"/login\">Log in / Sign up</a></nav></div></header>\n  <div class=\"container\"><p class=\"availability\">Product preview · The capabilities, pricing and performance figures below describe the product vision, not currently available services or verified guarantees. GitHub sign-in is available on this Worker-hosted version. No paid plans or workflow execution are enabled.</p></div><section class=\"hero\"><div class=\"container\"><h1>Scalable AI Workflow & Cloud Orchestration for Engineering Teams</h1><p>Originates empowers engineering teams to build, deploy, and scale autonomous AI workflows and serverless cloud infrastructure seamlessly.</p><div class=\"terminal\"><div class=\"terminal-header\"><div class=\"dot dot-red\"></div><div class=\"dot dot-yellow\"></div><div class=\"dot dot-green\"></div></div><div class=\"terminal-body\"><p>$ npm i -g originates-cli</p><p style=\"color:#8b949e;\">[+] Installed originates-cli v2.4.0</p><p>$ originates deploy --env production</p><p style=\"color:#58a6ff;\">[info] Orchestrating multi-agent graph...</p><p style=\"color:#7ee787;\">[success] Deployed to originates.dev (Latency: 28ms, SLA: 99.98%)</p></div></div></div></section>\n  <section class=\"container\"><div class=\"metrics\"><div class=\"metric-card\"><div class=\"metric-val\">99.98%</div><div class=\"metric-lbl\">Uptime SLA</div></div><div class=\"metric-card\"><div class=\"metric-val\">&lt;35ms</div><div class=\"metric-lbl\">Global Latency</div></div><div class=\"metric-card\"><div class=\"metric-val\">500M+</div><div class=\"metric-lbl\">Workflow Runs / Day</div></div></div></section>\n  <section id=\"features\" class=\"container\"><h2 class=\"section-title\">Core Platform Features</h2><div class=\"grid-3\"><div class=\"card\"><h3>Deterministic Multi-Agent Workflows</h3><p>Design complex, stateful multi-agent DAGs with strict execution guarantees, automated retry policies, and zero-loss state persistence.</p></div><div class=\"card\"><h3>Real-Time Trace & Cost Telemetry</h3><p>Gain full observability into token expenditure, model latency, and runtime execution metrics with sub-millisecond precision.</p></div><div class=\"card\"><h3>Serverless Edge Sandboxes</h3><p>Execute untrusted code and heavy AI workloads in secure, isolated MicroVM sandboxes deployed across global edge networks.</p></div></div></section>\n  <section id=\"architecture\" class=\"container\"><h2 class=\"section-title\">Enterprise Architecture</h2><div class=\"grid-3\"><div class=\"card\"><h3>Git-Native CI/CD</h3><p>Trigger workflow builds directly from git commits with automated preview environments and release pipelines.</p></div><div class=\"card\"><h3>Unified Model & API Gateway</h3><p>Connect seamlessly to top AI provider models with automated fallback, load balancing, and rate limiting.</p></div><div class=\"card\"><h3>Fine-Grained RBAC</h3><p>Enterprise-grade security featuring SAML/SSO, granular team role permissions, and SOC 2 Type II compliance.</p></div></div></section>\n  <section id=\"pricing\" class=\"container\"><h2 class=\"section-title\">Simple, Transparent Pricing</h2><div class=\"grid-3\"><div class=\"card pricing-card\"><h3>Developer</h3><div class=\"price\">$0<span style=\"font-size:14px;color:#8b949e;\">/mo</span></div><p>Ideal for side projects & individual developers building prototype AI pipelines.</p></div><div class=\"card pricing-card\" style=\"border-color:#2f81f7;\"><h3>Startup & Growth</h3><div class=\"price\">$149<span style=\"font-size:14px;color:#8b949e;\">/mo</span></div><p>For growing engineering teams requiring production SLAs and dedicated edge sandboxes.</p></div><div class=\"card pricing-card\"><h3>Enterprise</h3><div class=\"price\">Custom</div><p>Tailored cloud orchestration, custom model integrations, dedicated support & SLA guarantees.</p></div></div></section>\n  <section id=\"about\" class=\"container\"><div class=\"about\"><h2 style=\"margin-bottom:16px;\">About Originates Inc.</h2><p style=\"color:#8b949e;max-width:800px;margin:0 auto;\">Originates Inc. was founded by a team of veteran distributed systems and AI engineers dedicated to elevating cloud orchestration for high-performance engineering organizations. Operating as a high-velocity team of 12–50 engineers and researchers globally, we build the core backbone for next-generation AI workflows at originates.dev.</p></div></section>\n  <footer><div class=\"container\"><p>&copy; 2026 Originates Inc. (originates.dev) All rights reserved.</p><p style=\"margin-top:8px;\">Contact Us: <a href=\"mailto:admin@originates.dev\">admin@originates.dev</a> | <a href=\"mailto:ceo@originates.dev\">ceo@originates.dev</a></p></div></footer>\n  </body>\n</html>"},"/login":{"type":"text/html","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Sign in · Originates</title><link rel=\"stylesheet\" href=\"/account.css\"><script src=\"/auth.js\" defer></script></head><body><header><a class=\"brand\" href=\"/\">Originates<span>.dev</span></a><a href=\"/\">Back to home</a></header><main><p class=\"eyebrow\">YOUR WORKSPACE STARTS HERE</p><h1>Welcome to Originates.</h1><p class=\"muted\">Sign in securely with your GitHub account. Your Originates account is created automatically on your first sign-in.</p><a class=\"button primary\" id=\"github-login\" href=\"/auth/github\" style=\"display:block;text-align:center;text-decoration:none\">Continue with GitHub</a><p class=\"message\" id=\"message\" role=\"status\" aria-live=\"polite\"></p><div class=\"note\">We request your GitHub profile and email address only. We do not request access to your repositories, and never ask for your GitHub password on this website.</div><p class=\"muted\">Your account and session are stored in Cloudflare D1. Sign out at any time to revoke this site's session.</p><p class=\"note\">Account preview: AI workflow execution, cloud sandboxes, paid plans and billing are not enabled.</p><noscript><p>You can use the GitHub sign-in button without JavaScript.</p></noscript></main><footer>Originates · Powered by Cloudflare Workers + D1</footer></body></html>\n"},"/app":{"type":"text/html","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Account · Originates</title><link rel=\"stylesheet\" href=\"/account.css\"><script src=\"/account.js\" defer></script></head><body><header><a class=\"brand\" href=\"/\">Originates<span>.dev</span></a><button type=\"button\" id=\"logout\">Log out</button></header><main class=\"dashboard\"><p class=\"eyebrow\">ACCOUNT OVERVIEW</p><h1>Your account.</h1><p id=\"message\" class=\"message loading\" role=\"status\">Loading your account…</p><section class=\"panel\" id=\"profile\" hidden><p class=\"status\">Signed in with GitHub</p><h2 id=\"email\"></h2><p id=\"identity\" class=\"muted\"></p><p class=\"muted\">Account created <time id=\"created\"></time></p><p>Your session expires after seven days. Logging out immediately revokes this site's session.</p></section><section class=\"panel\"><h2>A foundation, not a simulated product.</h2><p>GitHub sign-in, persistent accounts and secure sessions are available. AI workflow execution, cloud sandboxes, API keys, billing and team permissions have not been implemented.</p><p class=\"muted\">This account page does not run or deploy AI workflows. There are no charges or paid plans enabled.</p></section><a href=\"/\">Return to the project homepage</a></main></body></html>\n"},"/auth.js":{"type":"text/javascript","body":"const messages={not_configured:'Sign-in is not configured yet. Please try again later.',invalid_state:'This sign-in request could not be verified. Please start again.',expired:'Your sign-in request expired. Please start again.',cancelled:'GitHub sign-in was cancelled. You can try again whenever you are ready.',invalid_callback:'This sign-in response was incomplete. Please start again.',provider:'GitHub sign-in could not be completed. Please try again.'};\nconst error=new URLSearchParams(location.search).get('error');\nif(error){document.querySelector('#message').textContent=messages[error]||'Unable to sign in. Please try again.';document.querySelector('#message').className='message error';history.replaceState(null,'','/login');}\nfetch('/api/me',{credentials:'same-origin'}).then(r=>{if(r.ok)location.replace('/app');}).catch(()=>{});\n"},"/account.js":{"type":"text/javascript","body":"const message=document.querySelector('#message');\nfetch('/api/me',{credentials:'same-origin'}).then(async r=>{\n  if(r.status===401){location.replace('/login');return;}\n  if(!r.ok)throw Error('Unable to load your account. Please refresh.');\n  const {user}=await r.json();document.querySelector('#email').textContent=user.name||user.login;document.querySelector('#identity').textContent='@'+user.login+(user.email?' · '+user.email:'');\n  const created=document.querySelector('#created');created.dateTime=new Date(user.createdAt).toISOString();created.textContent=new Date(user.createdAt).toLocaleDateString();\n  document.querySelector('#profile').hidden=false;message.textContent='';\n}).catch(()=>{message.textContent='Connection failed. Please refresh to load your account.';message.className='message error';});\ndocument.querySelector('#logout').addEventListener('click',async function(){\n  this.disabled=true;\n  try{const r=await fetch('/api/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();location.replace('/login');}\n  catch{message.textContent='Unable to log out. Please try again.';message.className='message error';this.disabled=false;}\n});\n"},"/account.css":{"type":"text/css","body":":root{color-scheme:light dark;--bg:#fff;--surface:#f9f8f7;--text:#242424;--muted:#595959;--border:#858585;--blue:#1769b3;--error:#ab2626;--success:#236237}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.6 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}a{color:var(--blue)}a,button,input{touch-action:manipulation}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--blue);outline-offset:3px}header{max-width:1120px;padding:24px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:16px}.brand{font-size:22px;font-weight:700;text-decoration:none;color:var(--text)}.brand span{color:var(--blue)}main{max-width:480px;margin:56px auto;padding:0 24px}h1{font-size:36px;line-height:1.2;margin:0 0 16px;letter-spacing:-1px}h2{font-size:24px;line-height:1.3}.eyebrow{font-size:14px;font-weight:600;color:var(--blue);letter-spacing:1px;margin-bottom:16px}.muted{color:var(--muted)}label{display:block;font-weight:600;margin-top:24px}input{display:block;width:100%;min-height:48px;border:1px solid var(--border);border-radius:8px;padding:10px 12px;background:var(--bg);color:var(--text);font:inherit;margin-top:8px}button,.button{min-height:48px;border:1px solid var(--border);border-radius:8px;font:inherit;font-weight:600;cursor:pointer;padding:12px 16px;background:var(--bg);color:var(--text)}button{font-family:inherit;font-size:16px;font-weight:600}.primary{background:var(--blue);color:#fff;border-color:var(--blue);width:100%;margin-top:24px}button:disabled{opacity:.65;cursor:wait}.switch{margin:8px 0 0;width:100%}.message{min-height:28px;margin:16px 0 0;overflow-wrap:anywhere}.error{color:var(--error)}.success{color:var(--success)}.note{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:16px;margin-top:32px;font-size:14px;color:var(--muted)}.dashboard{max-width:900px}.panel{padding:24px;background:var(--surface);border:1px solid var(--border);border-radius:8px;margin:32px 0}.panel p{overflow-wrap:anywhere}.status{color:var(--success);font-weight:600}footer{max-width:900px;margin:64px auto 24px;padding:0 24px;color:var(--muted);font-size:14px}.loading{color:var(--muted)}[hidden]{display:none!important}@media(prefers-color-scheme:dark){:root{--bg:#191919;--surface:#202020;--text:#fff;--muted:#bfbfbf;--border:#858585;--blue:#5e9fe8;--error:#f69a9a;--success:#90cfa7}.primary{background:#276cb9;color:white;border-color:#5e9fe8}}@media(max-width:500px){header{padding:20px}main{margin-top:32px;padding:0 20px}h1{font-size:32px}.panel{padding:20px}}\n"}};

const DAY = 86400000;
const SESSION_COOKIE = '__Host-originates_session';
const STATE_COOKIE = '__Host-originates_oauth';
const encoder = new TextEncoder();
function random() { return Array.from(crypto.getRandomValues(new Uint8Array(32)), x=>x.toString(16).padStart(2,'0')).join(''); }
async function sha(value) { return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(value))),x=>x.toString(16).padStart(2,'0')).join(''); }
async function challenge(value) { return btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(value))))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_'); }
function getCookie(request,name) { return (request.headers.get('Cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith(name+'='))?.slice(name.length+1); }
function cookie(name,value,age) { return `${name}=${value}; Path=/; Max-Age=${age}; Secure; HttpOnly; SameSite=Lax`; }
function equal(a,b) { if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let n=0;for(let i=0;i<a.length;i++)n|=a.charCodeAt(i)^b.charCodeAt(i);return n===0; }
function json(data,status=200) { return new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8'}}); }
function redirect(path,cookies=[]) { const h=new Headers({Location:path});for(const c of cookies)h.append('Set-Cookie',c);return new Response(null,{status:302,headers:h}); }
function secure(response) {
  const h=new Headers(response.headers);
  h.set('X-Content-Type-Options','nosniff');h.set('Referrer-Policy','no-referrer');h.set('X-Frame-Options','DENY');
  h.set('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");
  h.set('Cache-Control','no-store');h.set('Strict-Transport-Security','max-age=31536000');h.set('Permissions-Policy','camera=(), microphone=(), geolocation=()');
  return new Response(response.body,{status:response.status,headers:h});
}
async function currentUser(request,db) {
  const token=getCookie(request,SESSION_COOKIE);if(!/^[a-f0-9]{64}$/.test(token||''))return null;
  return db.prepare('SELECT users.id,users.github_login,users.email,users.name,users.created_at FROM sessions JOIN users ON users.id=sessions.user_id WHERE sessions.hash=? AND sessions.expires_at>?').bind(await sha(token),Date.now()).first();
}
async function rateLimit(db,request) {
  const key='oauth:'+await sha(request.headers.get('CF-Connecting-IP')||'local');const now=Date.now();
  const r=await db.prepare('INSERT INTO rate_limits(key,hits,resets) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET hits=CASE WHEN resets<=? THEN 1 ELSE hits+1 END,resets=CASE WHEN resets<=? THEN excluded.resets ELSE resets END RETURNING hits').bind(key,now+900000,now,now).first();
  return r.hits<=30;
}
export function createWorker({fetcher=globalThis.fetch,assets=STATIC_ASSETS}={}) {
  async function route(request,env) {
    const url=new URL(request.url),path=url.pathname;
    const configuredOrigin=env.APP_ORIGIN;
    if(!configuredOrigin||!/^https:\/\/[^/]+$/.test(configuredOrigin))return json({error:'Application origin has not been configured.'},503);
    const origin=url.origin;
    if(![configuredOrigin,env.PREVIEW_ORIGIN].includes(origin))return json({error:'This deployment is not the configured application origin.'},421);
    const db=env.DB;
    const configured=!!(db&&env.GITHUB_CLIENT_ID&&env.GITHUB_CLIENT_SECRET);
    if(path==='/api/health'&&request.method==='GET') {
      try { if(!db)throw Error();await db.prepare('SELECT id FROM users LIMIT 1').first();return json({ok:true,authentication:configured?'github':'not-configured',build:'cloudflare-free-v1'}); }
      catch {return json({ok:false,error:'Database is not ready.'},503);}
    }
    if(path==='/auth/github'&&request.method==='GET') {
      if(!configured)return redirect('/login?error=not_configured');
      if(!await rateLimit(db,request))return json({error:'Too many sign-in attempts. Try again in 15 minutes.'},429);
      const state=random(),verifier=random();
      await db.prepare('INSERT INTO oauth_states(hash,verifier,expires_at) VALUES(?,?,?)').bind(await sha(state),verifier,Date.now()+600000).run();
      const u=new URL('https://github.com/login/oauth/authorize');u.search=new URLSearchParams({client_id:env.GITHUB_CLIENT_ID,redirect_uri:origin+'/auth/github/callback',scope:'read:user user:email',state,code_challenge:await challenge(verifier),code_challenge_method:'S256'}).toString();
      return redirect(u.toString(),[cookie(STATE_COOKIE,state,600)]);
    }
    if(path==='/auth/github/callback'&&request.method==='GET') {
      const clear=cookie(STATE_COOKIE,'',0),state=url.searchParams.get('state'),code=url.searchParams.get('code');
      const fail=reason=>redirect('/login?error='+reason,[clear]);
      if(!configured)return fail('not_configured');
      if(!/^[a-f0-9]{64}$/.test(state||'')||!equal(state,getCookie(request,STATE_COOKIE)))return fail('invalid_state');
      const saved=await db.prepare('DELETE FROM oauth_states WHERE hash=? RETURNING verifier,expires_at').bind(await sha(state)).first();
      if(!saved||saved.expires_at<=Date.now())return fail('expired');
      if(url.searchParams.has('error'))return fail('cancelled');
      if(!code||code.length>1024)return fail('invalid_callback');
      try {
        const r=await fetcher('https://github.com/login/oauth/access_token',{method:'POST',headers:{Accept:'application/json','Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:env.GITHUB_CLIENT_ID,client_secret:env.GITHUB_CLIENT_SECRET,code,redirect_uri:origin+'/auth/github/callback',code_verifier:saved.verifier}),signal:AbortSignal.timeout(10000)});
        const token=await r.json();if(!r.ok||typeof token.access_token!=='string')return fail('provider');
        const headers={Authorization:'Bearer '+token.access_token,Accept:'application/vnd.github+json','User-Agent':'Originates-Login','X-GitHub-Api-Version':'2022-11-28'};
        const ur=await fetcher('https://api.github.com/user',{headers,signal:AbortSignal.timeout(10000)});const profile=await ur.json();
        if(!ur.ok||!Number.isSafeInteger(profile.id)||typeof profile.login!=='string')return fail('provider');
        let email=null;
        const er=await fetcher('https://api.github.com/user/emails',{headers,signal:AbortSignal.timeout(10000)});
        if(er.ok){const all=await er.json();if(Array.isArray(all))email=(all.find(e=>e.primary&&e.verified)||all.find(e=>e.verified))?.email||null;}
        const now=Date.now();
        const user=await db.prepare('INSERT INTO users(id,github_id,github_login,email,name,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(github_id) DO UPDATE SET github_login=excluded.github_login,email=excluded.email,name=excluded.name,updated_at=excluded.updated_at RETURNING id').bind(crypto.randomUUID(),String(profile.id),profile.login,email,typeof profile.name==='string'?profile.name:null,now,now).first();
        const session=random();const previous=getCookie(request,SESSION_COOKIE);
        if(/^[a-f0-9]{64}$/.test(previous||''))await db.prepare('DELETE FROM sessions WHERE hash=?').bind(await sha(previous)).run();
        await db.prepare('INSERT INTO sessions(hash,user_id,expires_at) VALUES(?,?,?)').bind(await sha(session),user.id,now+7*DAY).run();
        // The GitHub token is deliberately not stored; this app needs no repository access.
        return redirect('/app',[clear,cookie(SESSION_COOKIE,session,7*86400)]);
      }catch {return fail('provider');}
    }
    if(path==='/api/me'&&request.method==='GET') {
      if(!db)return json({error:'Account storage is not ready.'},503);
      const u=await currentUser(request,db);return u?json({user:{email:u.email,login:u.github_login,name:u.name,createdAt:u.created_at}}):json({error:'Please log in.'},401);
    }
    if(path==='/api/logout'&&request.method==='POST') {
      if(request.headers.get('Origin')!==origin||request.headers.get('Sec-Fetch-Site')==='cross-site')return json({error:'Request origin is not allowed.'},403);
      const token=getCookie(request,SESSION_COOKIE);
      if(db&&/^[a-f0-9]{64}$/.test(token||''))await db.prepare('DELETE FROM sessions WHERE hash=?').bind(await sha(token)).run();
      const response=json({ok:true});response.headers.append('Set-Cookie',cookie(SESSION_COOKIE,'',0));return response;
    }
    if(path.startsWith('/api/')||path.startsWith('/auth/'))return json({error:'Not found or method not allowed.'},404);
    if(request.method!=='GET'&&request.method!=='HEAD')return json({error:'Method not allowed.'},405);
    if(path==='/app') {if(!db||!await currentUser(request,db))return redirect('/login');}
    const asset=assets[path];if(!asset)return new Response('Page not found',{status:404,headers:{'Content-Type':'text/plain; charset=utf-8'}});
    return new Response(request.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type+'; charset=utf-8'}});
  }
  return {
    async fetch(request,env) {try{return secure(await route(request,env));}catch {return secure(json({error:'Service temporarily unavailable. Please try again.'},503));}},
    async scheduled(event,env,ctx) {const now=Date.now();await env.DB.batch([env.DB.prepare('DELETE FROM sessions WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM oauth_states WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM rate_limits WHERE resets<=?').bind(now)]);}
  };
}
export default createWorker();
